import{_ as i}from"./chunks/KEITH_RICHARDS_MESA_03.BE98nuu1.js";import{o as r,c as s,a2 as n,j as t,t as h,p as d}from"./chunks/framework.D21_4UK8.js";const l={class:"rock-card-contact"},u={class:"rock-copy-email-wrapper"},y=JSON.parse(`{"title":"The '78–'81 Story: How the Stones Met Mesa/Boogie","description":"","frontmatter":{},"headers":[],"relativePath":"history-mesa-stones.md","filePath":"history-mesa-stones.md"}`),m={name:"history-mesa-stones.md"},b=Object.assign(m,{setup(c){const a=d("Copy Email");function o(){navigator.clipboard.writeText("mainstaudiolabs@gmail.com"),a.value="Copied!",setTimeout(function(){a.value="Copy Email"},2e3)}return(p,e)=>(r(),s("div",null,[e[3]||(e[3]=n('<h1 id="the-78–-81-story-how-the-stones-met-mesa-boogie" tabindex="-1">The &#39;78–&#39;81 Story: How the Stones Met Mesa/Boogie <a class="header-anchor" href="#the-78–-81-story-how-the-stones-met-mesa-boogie" aria-label="Permalink to &quot;The &#39;78–&#39;81 Story: How the Stones Met Mesa/Boogie&quot;">​</a></h1><p><strong>Historical Archive &amp; Sound Notes · Main St Audio Labs</strong></p><hr><img src="'+i+'" alt="Keith Richards with his Mesa Boogie Mark I" style="max-height:400px;display:block;margin:1.5rem auto;border:2px solid var(--vp-c-border);border-radius:6px;"><p>In the late 1970s, as the Rolling Stones were preparing for their <em>Some Girls</em> tour and a string of legendary studio sessions, a critical piece of their iconic guitar tone was forged—not in a massive London factory, but in a small &quot;cottage industry&quot; workshop in California. The story of how Keith Richards and the Stones acquired their legendary 100W Mesa/Boogie Mark I amplifiers is a fascinating chapter in rock history.</p><h2 id="the-birth-of-the-boogie" tabindex="-1">The Birth of the Boogie <a class="header-anchor" href="#the-birth-of-the-boogie" aria-label="Permalink to &quot;The Birth of the Boogie&quot;">​</a></h2><p>The story begins with Randall (Randy) Smith, who started out modifying small Fender Princeton combos in the back of Prune Music, a store in Lagunitas / Mill Valley, California. Smith would take these modest practice amps and hot-rod them, stuffing them with massive Bassman transformers and high-gain circuits.</p><p>The legend goes that when Carlos Santana played one of these early modified prototypes, he famously exclaimed, <em>&quot;Man, that little thing really boogies!&quot;</em>—and thus, the Mesa/Boogie name was born.</p><p>These early Mark I amplifiers were revolutionary: they packed a staggering 100 watts of RMS power into a compact 1x12&quot; format. To handle this immense power without blowing up, Smith loaded them with heavy-duty speakers, most notably the Electro-Voice EVM-12L or Altec 417, housed in beautifully crafted hardwood cabinets. The Mark I wasn&#39;t a channel-switcher in the modern sense; instead, it featured two inputs. Input 1 offered four stages of 12AX7-driven gain for searing lead tones, while Input 2 bypassed one stage for a cleaner, &quot;hot-rodded Fender&quot; rhythm tone.</p><h2 id="the-call-from-ian-stewart" tabindex="-1">The Call from Ian Stewart <a class="header-anchor" href="#the-call-from-ian-stewart" aria-label="Permalink to &quot;The Call from Ian Stewart&quot;">​</a></h2><p>By early 1977, the Rolling Stones were preparing for their first club dates in 14 years—the famous El Mocambo shows in Toronto, Canada, which would eventually make up side three of the <em>Love You Live</em> album. Word of these incredibly loud, touch-sensitive California amplifiers had reached the Stones&#39; camp.</p><p>According to Randy Smith, the connection started with a surprising phone call. As Smith recalled: <em>&quot;At that point, building amps was a cottage industry and I did everything. So, I picked it up and it was [Stones pianist] Ian Stewart. He said, &#39;We&#39;re interested in trying a Boogie.&#39; They&#39;d heard a lot about them and asked if I would send some. I said, &#39;I really can&#39;t do that. I&#39;m a one-person shop; I don&#39;t give away amps.&#39; And he said, &#39;We&#39;re the Rolling Stones, we don&#39;t pay for amps.&#39;&quot;</em></p><p>During this brief stalemate, Smith could hear Keith Richards in the background, feeding lines to Stewart. Smith asked to speak to Richards directly.</p><p><em>&quot;Keith gets on the line and he&#39;s just the best—super-friendly guy,&quot;</em> Smith noted. <em>&quot;He says, &#39;Hey man. How you doing? Yeah, I&#39;d love to get my hands on one of your amplifiers.&#39; We went through the same thing and he said, &#39;Well, it just doesn&#39;t seem right. We haven&#39;t paid for gear in forever. We just don&#39;t.&#39; I said, &#39;Well, I just don&#39;t give gear away because I&#39;m basically just a starving cat here...&#39;&quot;</em></p><p>Smith, taking a massive gamble with one of the biggest rock bands on the planet, made a bold proposition: The Stones should buy the amp. If they didn&#39;t like it, they could send it back for a full refund. Or better yet, because there was such a massive waitlist for Boogies, they could simply sell it for a profit if it wasn&#39;t for them.</p><p>After a long, pregnant pause, Richards replied: <em>&quot;Well, yeah, mate. That would be a really good idea, except I already know I want the amp. There&#39;s no doubt about that. I played Santana&#39;s when he sat in with us. And I don&#39;t want just one, I want six of &#39;em.&quot;</em></p><h2 id="the-mark-i-hits-the-stage-and-studio" tabindex="-1">The Mark I Hits the Stage and Studio <a class="header-anchor" href="#the-mark-i-hits-the-stage-and-studio" aria-label="Permalink to &quot;The Mark I Hits the Stage and Studio&quot;">​</a></h2><p>Those first six Mesa/Boogie Mark I amplifiers—featuring the 5-band graphic EQ and high-headroom speakers—became the cornerstone of the Stones&#39; guitar sound for the next half-decade.</p><p>Photographs from the March 1977 El Mocambo shows clearly show Richards (and Ronnie Wood) playing their new hardwood Boogies. Richards&#39; amp famously acquired a cigarette burn right above the Treble knob during these very gigs.</p><p>These amplifiers were subsequently packed up and shipped to <em>Pathé Marconi Studios</em> in Paris for the legendary <em>Some Girls</em> sessions later that year. The sheer headroom and articulate attack of the 100W 6L6 power section, combined with the precision of the graphic EQ, allowed Richards and Wood to craft tones that were punchy and clean, yet retained a gritty, muscular edge—perfectly cutting through the mix on tracks like &quot;Beast of Burden&quot; and &quot;Shattered&quot;.</p><p>The Boogies remained the band&#39;s primary backline through the recording of <em>Emotional Rescue</em> (1979-1980 at Compass Point and Pathé Marconi) and <em>Tattoo You</em> (1981). Over the years, the Rolling Stones would go on to purchase—and fully pay for—over 40 Mesa/Boogie amplifiers.</p><h2 id="the-end-of-an-era-and-the-return-to-the-roots" tabindex="-1">The End of an Era and the Return to the Roots <a class="header-anchor" href="#the-end-of-an-era-and-the-return-to-the-roots" aria-label="Permalink to &quot;The End of an Era and the Return to the Roots&quot;">​</a></h2><p>The Mesa/Boogie Mark I (and later Mark II and III models) remained the undisputed core of Richards&#39; guitar rig for over a decade. They powered the massive <em>Steel Wheels</em> tour in 1989 and were still heavily featured during his solo <em>X-Pensive Winos</em> tours in 1992 and 1993. In fact, that original 1977 Mark I (Serial Number A804) was sent back to the Mesa factory in California for a tune-up right before the &#39;92 Winos tour.</p><p>However, by the mid-1990s (<em>Voodoo Lounge</em> and <em>Bridges to Babylon</em>), Keith began transitioning back to his roots. He rediscovered his love for the loose, organic, uncompressed crunch of 1950s <strong>Fender Tweed</strong> amplifiers—specifically the High Power Tweed Twins and Tweed Deluxes—which have remained the staple of his live and studio sound ever since.</p><blockquote><p>🎸 <strong>Looking for that raw 50s Tweed tone?</strong><br> If you want to experience the raw, touch-sensitive breakup of the Tweed era that Keith eventually returned to, check out our <strong><a href="/midnight-rambler.html">Midnight Rambler plugin</a></strong>—a faithful neural emulation of a cranked 1950s Tweed Deluxe (5E3).</p></blockquote><p>Today, that original 1977 Mark I with the cigarette burn still exists, a physical testament to a pivotal moment when a boutique California amp builder helped redefine the sound of the world&#39;s greatest rock and roll band.</p><blockquote><p><em>Story adapted from Dave Hunter&#39;s article &quot;Keith Richards’ 1977 Mesa/Boogie Mark I&quot; via Vintage Guitar® magazine. Read the full original article <a href="https://www.vintageguitar.com/55906/keith-richards-1977-mesa-boogie-mark-i/" target="_blank" rel="noreferrer">here</a>.</em></p></blockquote><hr><div style="text-align:center;margin:2rem 0;"><a href="/tattoo-you" class="rock-btn rock-btn-primary" style="display:inline-block;padding:0.6rem 1.5rem;">← Back to Tattoo You Manual</a></div>',29)),t("div",l,[e[1]||(e[1]=t("div",{class:"rock-card-contact-title"},"Have Archive Photos or Session Stories?",-1)),e[2]||(e[2]=t("p",{class:"rock-card-contact-desc"},"If you have archival info or stories regarding the Stones' late '70s and early '80s studio rigs, we'd love to hear from you:",-1)),t("div",u,[e[0]||(e[0]=t("span",{class:"rock-email-text"},"mainstaudiolabs@gmail.com",-1)),t("button",{class:"rock-copy-btn",onClick:o},h(a.value),1)])])]))}});export{y as __pageData,b as default};
